#!/usr/bin/env python3
import pathlib,subprocess,json,argparse
p=argparse.ArgumentParser();p.add_argument("--unit-calibration",action="store_true");args=p.parse_args()
root=pathlib.Path(__file__).resolve().parents[1];out=root/'build/english6';out.mkdir(parents=True,exist_ok=True);src=root/'experiments/english6'
names='SIL AA AE AH AO AW AY B CH D DH EH ER EY F G HH IH IY JH K L M N NG OW OY P R S SH T TH UH UW V W Y Z ZH'.split()
# Rounded female aggregate F1..F4 facts from Hillenbrand et al. Table V (1995).
vowels={'IY':[440,2760,3370,4350],'IH':[480,2360,3050,4330],'EH':[730,2060,2980,4290],'AE':[670,2350,2970,4290],'AA':[940,1550,2820,4300],'AO':[780,1140,2820,3920],'AH':[750,1430,2930,4090],'ER':[520,1590,1930,3910],'UW':[460,1110,2740,4120],'UH':[520,1230,2830,4050],'EY':[540,2530,3050,4320],'OW':[560,1040,2830,3930]}
vowels.update(AY=vowels['AA'],AW=vowels['AA'],OY=vowels['AO'])
profiledir=out/'unit' if args.unit_calibration else out;profiledir.mkdir(exist_ok=True);profiles=profiledir/'proto6_profiles.h'
if not args.unit_calibration and not profiles.exists() and (src/'calibrated_profiles.h').exists():profiles.write_text((src/'calibrated_profiles.h').read_text())
if not profiles.exists():
 text='/* Original derived coefficients; aggregate vowel facts credited in REFERENCES.md. */\nstatic const float p6_formants[40][4]={\n'+''.join('{'+','.join(str(x)+'.0f' for x in vowels.get(p,vowels['AH']))+'}, /* '+p+' */\n' for p in names)+'};\nstatic const float p6_voice_scale[7]={1,.86f,1.04f,.93f,1.14f,.92f,1};\nstatic const float p6_pitch_gain[7][40][3]={\n'+','.join('{'+','.join('{1,1,1}' for _ in names)+'}' for _ in range(7))+'};\n';profiles.write_text(text)
header=(root/'core/kira.h').read_text().replace('#include <stdint.h>','#include <stdint.h>\n#include "proto6_state.h"').replace('} k9_engine;','  p6_state prototype;\n} k9_engine;');(out/'kira.h').write_text(header)
base=(root/'core/engine.c').read_text();start=base.index('    phone = &bank[e->phone];');end=base.index('    e->sample++;',start);adapter=base[:start]+'    p6_process(e,out+i*2);\n'+base[end:];adapter=adapter.replace('#include "memory.h"','#include "memory.h"\nvoid p6_process(k9_engine*,float*);');(out/'adapter.c').write_text(adapter)
bridge=(root/'studio/bridge.c').read_text().replace('#include "../core/face.h"','#include "kira.h"\n#include "face.h"').replace('#include "../core/kira.h"','').replace('#include "../core/library.h"','#include "library.h"').replace('#include "../factory/songs.h"','#include "../../factory/songs.h"');bridge+='''\n__attribute__((visibility("default"))) void web_probe(unsigned p,unsigned n,unsigned v,unsigned vel){web_init();web_engine.voice=v;k9_note(&web_engine,p,n,vel);web_engine.phone_frames=22050;}\n__attribute__((visibility("default"))) float *web_diagnostics(void){static float d[8];d[0]=web_engine.prototype.raw_peak;d[1]=web_engine.prototype.band_peak;d[2]=web_engine.prototype.source_peak;d[3]=(float)web_engine.prototype.over;d[4]=(float)web_engine.prototype.nonfinite;d[5]=(float)sizeof(p6_state);d[6]=(float)sizeof(k9_engine);return d;}\n''';(out/'bridge.c').write_text(bridge)
cmd=['cc','-shared','-fPIC','-O2','-ffp-contract=off','-I'+str(profiledir),'-I'+str(out),'-I'+str(src),'-Icore',str(out/'adapter.c'),str(src/'proto6.c'),'core/codec.c','core/library.c','core/tables.c','core/face.c',str(out/'bridge.c'),'-o',str(out/('prototype-unit.so' if args.unit_calibration else 'prototype.so'))];subprocess.run(cmd,cwd=root,check=True)
(out/'targets.json').write_text(json.dumps({'facts_source':'Hillenbrand et al. 1995 Table V; female averages, rounded to 10Hz','formants':vowels,'audio_imported':False,'external_code_or_coefficients_copied':False},indent=2)+'\n');print('Isolated English6 kernel built; production unchanged.')
